describe('500 Error Page Display', () => {
  beforeEach(() => {
    cy.visit('http://localhost:3000');
  });

  it('should display error page when server returns 500 error', () => {
    cy.intercept('GET', '/api/data', {
      statusCode: 500,
      body: { error: 'Internal Server Error' }
    }).as('serverError');

    cy.get('[data-testid="fetch-data-button"]').click();
    cy.wait('@serverError');

    cy.get('[data-testid="error-page"]').should('be.visible');
    cy.get('[data-testid="error-title"]').should('contain', '500');
    cy.get('[data-testid="error-message"]').should('contain', 'Internal Server Error');
  });

  it('should display error page with retry option on 500 error', () => {
    cy.intercept('GET', '/api/data', {
      statusCode: 500,
      body: { error: 'Internal Server Error' }
    }).as('serverError');

    cy.get('[data-testid="fetch-data-button"]').click();
    cy.wait('@serverError');

    cy.get('[data-testid="error-page"]').should('be.visible');
    cy.get('[data-testid="retry-button"]').should('be.visible');
    cy.get('[data-testid="retry-button"]').should('not.be.disabled');
  });

  it('should handle multiple consecutive 500 errors gracefully', () => {
    cy.intercept('GET', '/api/data', {
      statusCode: 500,
      body: { error: 'Internal Server Error' }
    }).as('serverError');

    cy.get('[data-testid="fetch-data-button"]').click();
    cy.wait('@serverError');
    cy.get('[data-testid="error-page"]').should('be.visible');

    cy.get('[data-testid="retry-button"]').click();
    cy.wait('@serverError');
    cy.get('[data-testid="error-page"]').should('be.visible');
    cy.get('[data-testid="error-count"]').should('contain', '2');
  });

  it('should display error page with proper styling and accessibility', () => {
    cy.intercept('GET', '/api/data', {
      statusCode: 500,
      body: { error: 'Internal Server Error' }
    }).as('serverError');

    cy.get('[data-testid="fetch-data-button"]').click();
    cy.wait('@serverError');

    cy.get('[data-testid="error-page"]').should('have.css', 'display', 'block');
    cy.get('[data-testid="error-title"]').should('have.attr', 'role', 'heading');
    cy.get('[data-testid="error-message"]').should('have.attr', 'aria-live', 'polite');
  });
});
